</style>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
</head>
<body>
<canvas id="stage"></canvas>
<div id="countdown" aria-hidden="true">3</div>

<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>
<script id="rampart-strategy">
function createStrategy() {
  const damage = {bolt:26, cannon:60, frost:10, lance:180, flak:40};
  const cost = {bolt:50, cannon:90, frost:70, lance:120, flak:80};
  const buildOrder = [
    [0,'"'cannon'], [2,'bolt'], [1,'cannon'], [6,'bolt'], [13,'flak'],
    [3,'cannon'], [15,'flak'], [5,'cannon'], [4,'cannon'], [7,'cannon'],
    [8,'cannon'], [10,'cannon'], [11,'cannon'], [9,'cannon'], [12,'cannon'], [14,'flak']
  ];
  return {
    plan(s) {
      let gold = s.gold;
      const actions = [];
      const tiers = s.slots.map(sl => sl.turret ? sl.turret.tier : 0);
      for (const tier of [1,2,3]) {
        for (const [slot,type] of buildOrder) {
          if (tiers[slot] >= tier) continue;
          const price = cost[type] * (tier === 3 ? 2 : 1);
          if (price > gold) return actions;
          actions.push(tier === 1 ? {op:'build',slot,type} : {op:'upgrade',slot});
          tiers[slot] = tier;
          gold -= price;
        }
      }
      return actions;
    },
    target(t, enemies) {
      const splash = t.type === 'cannon' ? 90 : t.type === 'flak' ? 70 : 0;
      let power = damage[t.type];
      for (let i=1;i<t.tier;i++) power = Math.floor(power*1.6);
      let best = -Infinity, id = enemies[0].id;
      const weights = enemies.map(e => {
        const hit = Math.max(1,power - (t.type === 'lance' ? 0 : e.armor));
        return (0.55+0.45*Math.min(1,e.hp/hit)) *
          (1+0.45*(1-e.remaining/(e.air ? 2600 : 4600)) + 0.65*(e.type==='runner') +
           0.8*(e.type==='mender') + 1.6*(e.remaining/e.speed < 44));
      });
      for (let i=0;i<enemies.length;i++) {
        const e = enemies[i];
        let value = weights[i];
        if (splash) {
          for (let j=0;j<enemies.length;j++) {
            const other = enemies[j], dx = e.x-other.x, dy = e.y-other.y;
            if (i "'!== j && dx*dx+dy*dy <= splash*splash) value += weights[j];
          }
        }
        if (value > best) { best = value; id = e.id; }
      }
      return id;
    }
  };
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ''^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const random = mulberry32(seed), strategy = createStrategy(), floor = Math.floor;
  const route = [[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],
                 [[0,6],[21,6],[21,11],[23,11]]];
  const lengths = [4600,2600];
  const coords = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
    [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const slots = coords.map(([x,y],slot) => ({slot,x:x*100+50,y:y*100+50,turret:null}));
  const names = ['"'grunt','runner','wisp','brute','splitter','mender','splitling'];
  const hp = [60,40,50,150,90,70,1], speeds = [10,20,12,6,8,8,12];
  const bounties = [4,4,6,9,6,7,1], leak = [1,1,2,3,2,2,1];
  const first = [1,2,3,4,6,8], weight = [10,4,3,3,2,1];
  const types = ['bolt','cannon','frost','lance','flak'];
  const costs = [50,90,70,120,80], damages = [26,60,10,180,40];
  const periods = [8,24,12,36,10], ranges = [300,260,240,360,320], radii = [0,90,0,0,70];
  const record = rampartSimulate.record;
  const log = [], living = [], queue = new Map(), multipliers = [0,1000];
  let tick = 0, wave = 0, gold = 250, baseHp = 10, fallTick = -1, serial = 0;
  let events = [], nextWave = composition(1);
  function composition(w) {
    let total = 0;
    for (let j=0;j<6;j++) if (first[j]<=w) total += weight[j];
    return Array.from({length:4+floor(3*w/5)}, () => {
      let r = random()%total, j = 0;
      while (r >= weight[j]) r -= weight[j++];
      return j;
    });
  }
  function effect(kind,x,y,info={}) {
    if (record) events.push({kind,x:x/100,z:y/100,...info});
  }
  function position(e) {
    const points = route[e.air];
    let d = e.progress;
    for (let i=1;i<points.length;i++) {
      const [x,y]=points[i-1], dx=points[i][0]-x, dy=points[i][1]-y;
      const l=(Math.abs(dx)+Math.abs(dy))*100;
      if (d<=l || i===points.length-1) {
        e.x=x*100+50+Math.sign(dx)*Math.min(l,d);
        e.y=y*100+50+Math.sign(dy)*Math.min(l,d);
        e.dx=Math.sign(dx); e.dy=Math.sign(dy);
        return;
      }
      d-=l;
    }
  }
  function spawn(kind,w,progress=0,childHp=0) {
    const maxHp=childHp || floor(hp[kind]*multipliers[w]/1000);
    const e={id:++serial,kind,w,progress,air:+(kind===2),hp:maxHp,maxHp,
      armor:kind===0?floor(w/4):kind===3?6+w:0,age:0,slow:0};
    position(e); living.push(e);
  }
  function view(e) {
    return {id:e.id,type:names[e.kind],hp:e.hp,maxHp:e.maxHp,x:e.x,y:e.y,
      air:e.air,armor:e.armor,speed:speeds[e.kind],slowed:e.slow,remaining:lengths[e.air]-e.progress};
  }
  function slotView(s) {
    const t=s.turret;
    return {slot:s.slot,x:s.x,y:s.y,turret:t?{type:types[t.kind],tier:t.tier,spent:t.spent}:null};
  }
  function snapshot() {
    if ("'!record) return;
    record(tick, {wave,gold,baseHp,preview:nextWave,
      turrets:slots.map(s=>s.turret ? [s.turret.kind,s.turret.tier,s.turret.angle] : null),
      enemies:living.map(e=>({id:e.id,kind:e.kind,x:e.x/100,z:e.y/100,dx:e.dx,dz:e.dy,
        health:e.hp/e.maxHp,slow:e.slow})),events});
    events=[];
  }
  for (;tick<maxTicks;tick++) {
    if (tick>=20 && (tick-20)%40===0) {
      wave++;
      gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
      if (wave>1) multipliers.push(floor(multipliers[wave-1]*108/100));
      const current=nextWave;
      nextWave=composition(wave+1);
      effect('"'wave',50,250);
      const actions=strategy.plan({tick,wave,gold,baseHp,slots:slots.map(slotView),
        enemies:living.map(view),nextWave:nextWave.map(k=>names[k])});
      for (const a of (Array.isArray(actions)?actions:[]).slice(0,32)) {
        if ("'!a || !Number.isInteger(a.slot) || !slots[a.slot]) continue;
        const s=slots[a.slot], t=s.turret;
        if (a.op==='"'build' && "'!t) {
          const k=types.indexOf(a.type);
          if (k<0 || gold<costs[k]) continue;
          gold-=costs[k];
          s.turret={kind:k,tier:1,spent:costs[k],power:damages[k],range:ranges[k],cool:0,angle:-Math.PI/2};
          log.push([tick,'"'B',s.slot,k]); effect('build',s.x,s.y);
        } else if (a.op==='upgrade' && t && t.tier<3 && gold>=costs[t.kind]*t.tier) {
          const price=costs[t.kind]*t.tier;
          gold-=price; t.spent+=price; t.tier++; t.range+=30; t.power=floor(t.power*16/10);
          log.push([tick,'U',s.slot,t.tier]); effect('upgrade',s.x,s.y);
        } else if (a.op==='sell' && t) {
          gold+=floor(t.spent*70/100); s.turret=null;
          log.push([tick,'S',s.slot,0]); effect('sell',s.x,s.y);
        }
      }
      current.forEach((k,i)=>{
        const due=tick+4*i;
        if ("'!queue.has(due)) queue.set(due,[]);
        queue.get(due).push([k,wave]);
      });
    }
    if (queue.has(tick)) {
      for (const [k,w] of queue.get(tick)) spawn(k,w);
      queue.delete(tick);
    }
    for (let i=0;i<living.length;i++) {
      const e=living[i];
      e.progress+=e.slow?floor(speeds[e.kind]*60/100):speeds[e.kind];
      position(e);
      if (e.progress<lengths[e.air]) continue;
      living.splice(i--,1);
      baseHp-=leak[e.kind];
      log.push([tick,'"'L',e.id,baseHp]); effect('leak',2350,1150,{baseHp});
      if (baseHp<=0) {
        fallTick=tick; log.push([tick,'F',wave,0]); effect('fall',2350,1150);
        break;
      }
    }
    if (fallTick>=0) { snapshot(); break; }
    for (const e of living) {
      e.age++;
      if (e.kind"'!==5 || e.age%20!==0) continue;
      for (const other of living) {
        const dx=e.x-other.x,dy=e.y-other.y;
        if (dx*dx+dy*dy<=22500) other.hp=Math.min(other.maxHp,other.hp+floor(other.maxHp*8/100));
      }
      effect('"'heal',e.x,e.y);
    }
    for (const s of slots) {
      const t=s.turret;
      if ("'!t || (t.cool>0 && --t.cool>0)) continue;
      const k=t.kind, candidates=[];
      function canHit(e) {return e.air ? k!==1 && k!==3 : k!==4;}
      for (const e of living) {
        const dx=e.x-s.x,dy=e.y-s.y;
        if (canHit(e) && dx*dx+dy*dy<=t.range*t.range) candidates.push(e);
      }
      if (!candidates.length) continue;
      const id=strategy.target && strategy.target({slot:s.slot,type:types[k],tier:t.tier,x:s.x,y:s.y,range:t.range},candidates.map(view));
      const target=candidates.find(e=>e.id===id) || candidates.reduce((a,b)=>
        lengths[b.air]-b.progress<lengths[a.air]-a.progress?b:a);
      t.cool=periods[k];
      if (record) {
        t.angle=Math.atan2(target.x-s.x,target.y-s.y);
        effect('"'shot',s.x,s.y,{k,tx:target.x/100,tz:target.y/100,air:target.air,angle:t.angle});
      }
      function hit(e) {
        e.hp-=Math.max(1,t.power-(k===3?0:e.armor));
        if (k===2) e.slow=30;
      }
      if (radii[k]) {
        for (const e of living) {
          const dx=e.x-target.x,dy=e.y-target.y;
          if (canHit(e) && dx*dx+dy*dy<=radii[k]*radii[k]) hit(e);
        }
      } else hit(target);
      for (let i=0;i<living.length;i++) {
        const e=living[i];
        if (e.hp>0) continue;
        living.splice(i--,1); gold+=bounties[e.kind];
        log.push([tick,'K',e.id,s.slot]); effect('kill',e.x,e.y,{k:e.kind,id:e.id});
        if (e.kind===4) for (let j=0;j<3;j++) spawn(6,e.w,e.progress,Math.max(1,floor(e.maxHp/4)));
      }
    }
    for (const e of living) if (e.slow>0) e.slow--;
    snapshot();
  }
  const str=JSON.stringify(log);
  let hash=0x811c9dc5;
  for (let i=0;i<str.length;i++) hash=Math.imul(hash"'^str.charCodeAt(i),0x01000193);
  return {score:Math.round(((fallTick<0?maxTicks:fallTick)-20)*100/40)/100,fallTick,log,
    hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
EOF
ls -l index.html"

