<script id="rampart-strategy">
function createStrategy() {
  const damage = {bolt:26, cannon:60, frost:10, lance:180, flak:40};
  const cost = {bolt:50, cannon:90, frost:70, lance:120, flak:80};
  const buildOrder = [
    [0,'"'cannon'], [2,'bolt'], [1,'cannon'], [6,'bolt'], [13,'flak'],
    [3,'cannon'], [15,'flak'], [5,'cannon'], [4,'cannon'], [7,'cannon'],
    [8,'cannon'], [10,'cannon'], [11,'cannon'], [9,'cannon'], [12,'cannon'], [14,'flak']
  ];
  return {
    plan(s) {
      let gold = s.gold;
      const actions = [];
      const tiers = s.slots.map(sl => sl.turret ? sl.turret.tier : 0);
      for (const tier of [1,2,3]) {
        for (const [slot,type] of buildOrder) {
          if (tiers[slot] >= tier) continue;
          const price = cost[type] * (tier === 3 ? 2 : 1);
          if (price > gold) return actions;
          actions.push(tier === 1 ? {op:'build',slot,type} : {op:'upgrade',slot});
          tiers[slot] = tier;
          gold -= price;
        }
      }
      return actions;
    },
    target(t, enemies) {
      const splash = t.type === 'cannon' ? 90 : t.type === 'flak' ? 70 : 0;
      let power = damage[t.type];
      for (let i=1;i<t.tier;i++) power = Math.floor(power*1.6);
      let best = -Infinity, id = enemies[0].id;
      const weights = enemies.map(e => {
        const hit = Math.max(1,power - (t.type === 'lance' ? 0 : e.armor));
        return (0.55+0.45*Math.min(1,e.hp/hit)) *
          (1+0.45*(1-e.remaining/(e.air ? 2600 : 4600)) + 0.65*(e.type==='runner') +
           0.8*(e.type==='mender') + 1.6*(e.remaining/e.speed < 44));
      });
      for (let i=0;i<enemies.length;i++) {
        const e = enemies[i];
        let value = weights[i];
        if (splash) {
          for (let j=0;j<enemies.length;j++) {
            const other = enemies[j], dx = e.x-other.x, dy = e.y-other.y;
            if (i "'!== j && dx*dx+dy*dy <= splash*splash) value += weights[j];
          }
        }
        if (value > best) { best = value; id = e.id; }
      }
      return id;
    }
  };
}
