  const lengths = [4600,2600];
  const coords = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
    [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const slots = coords.map(([x,y],slot) => ({slot,x:x*100+50,y:y*100+50,turret:null}));
  const names = ['"'grunt','runner','wisp','brute','splitter','mender','splitling'];
  const hp = [60,40,50,150,90,70,1], speeds = [10,20,12,6,8,8,12];
  const bounties = [4,4,6,9,6,7,1], leak = [1,1,2,3,2,2,1];
  const first = [1,2,3,4,6,8], weight = [10,4,3,3,2,1];
  const types = ['bolt','cannon','frost','lance','flak'];
  const costs = [50,90,70,120,80], damages = [26,60,10,180,40];
