      if(type==='flak'&&Math.abs(positions[i][1]-6)>3&&positions[i][0]<18)continue;
      const spent=budget[old.type]*(old.tier===3?4:2),refund=Math.floor(spent*.7);
      const balance=cash+refund;
      if(balance<budget[type])continue;
      const tier=balance>=budget[type]*4?3:balance>=budget[type]*2?2:1;
      towers[i]={type,tier};
      const loss=forecast(state,towers,spawns)+.5+(3-tier)*.26;
      towers[i]=old;
      if(loss<best){best=loss;bestActions=actionList.concat([{op:'sell',slot:i},{op:'build',slot:i,type}]);
      for(let j=1;j<tier;j++)bestActions.push({op:'upgrade',slot:i});}
      }
    }
