 return {
 plan(state) {
   const levels=state.slots.map(s=>s.turret?s.turret.tier:0);
   const airDemand=state.enemies.reduce((n,e)=>n+(e.air?e.hp*(1-e.remaining/2800):0),0);
   const airAdjustment=Math.min(12,airDemand/160)*p.pressure;
   let gold=state.gold, out=[];
   for(let n=0;n<32;n++){
     let best=Infinity,slot=-1;
     for(let i=0;i<16;i++){
       if(levels[i]===3)continue;
       const priority=p.rank[i][levels[i]]-(p.types[i]==='flak'?airAdjustment:0);
       if(priority<best){best=priority;slot=i;}
     }
     if(slot<0)break;
     const type=state.slots[slot].turret?.type || p.types[slot],tier=levels[slot],price=cost[type]*(tier===2?2:1);
     if(price>gold)break;
     out.push(tier?{op:'upgrade',slot}:{op:'build',slot,type});
     gold-=price;levels[slot]++;
   }
   return redeploy(state,out,levels,gold);
 },
 target(t,es){
   const r=t.type==='cannon'?90:t.type==='flak'?70:0;
   const power=damage[t.type][t.tier-1];
   const weights=es.map(e=>{
     if(t.type==='frost'){
       const prog=1-e.remaining/(e.air?2800:4600);
       const loss=e.type==='brute'?3:e.type==='grunt'||e.type==='runner'||e.type==='splitling'?1:2;
       return (e.slowed?.06:1)*(1+loss)*(1+3*prog*prog);
     }
     const hit=Math.max(1,power-(t.type==='lance'?0:e.armor));
     const progress=1-e.remaining/(e.air?2800:4600);
     const priority=1+p.ahead*progress*progress + (e.type==='runner'?p.runner:e.type==='mender'?p.mender:0);
     const urgency=e.remaining/e.speed<70?p.close:0;
     return (0.65+0.35*Math.min(1,e.hp/hit))*(priority+urgency+p.finish*(1-e.hp/e.maxHp));
   });
   let best=-Infinity,id=es[0].id;
   for(let i=0;i<es.length;i++){
     let score=weights[i];
     if(r)for(let j=0;j<es.length;j++){
       if(i===j)continue;
       const dx=es[i].x-es[j].x, dy=es[i].y-es[j].y;
       if(dx*dx+dy*dy<=r*r)score+=weights[j];
     }
     if(score>best){best=score;id=es[i].id;}
   }
   return id;
 }
